Ltac pl_move_rw AGL PLX m0 m1 H side :=
  apply (rw_cells_agree_nw asegs m0 m1) in H;
  [ | eapply agree_sub; [exact AGL|]; cbv beta;
      let xx := fresh "xx" in let Hxx := fresh "Hxx" in intros xx Hxx;
      cbn [cells_size csize Nat.add Z.of_nat Pos.of_succ_nat Pos.succ Pos.add Pos.mul Z.to_nat Pos.to_nat] in Hxx; apply PLX; side Hxx ].
Ltac pl_move_wr AGL PLX m0 m1 H side :=
  apply (wr_at_agree_nw asegs m0 m1) in H;
  [ | eapply agree_sub; [exact AGL|]; cbv beta;
      let xx := fresh "xx" in let Hxx := fresh "Hxx" in intros xx Hxx; apply PLX; side Hxx ].

